import hashlib,rbd

def backup(image,restored,repair):
    before=image.flags();invalid=rbd.RBD_FLAG_OBJECT_MAP_INVALID|rbd.RBD_FLAG_FAST_DIFF_INVALID
    if repair and before&invalid:image.rebuild_object_map()
    after=image.flags()
    if repair and after&invalid:raise ValueError('object-map rebuild did not clear invalid flags')
    digest=hashlib.sha256();size=image.size()
    for offset in range(0,size,65536):
        data=image.read(offset,min(65536,size-offset));digest.update(data);restored.write(data,offset)
    restored.flush()
    actual=hashlib.sha256()
    for offset in range(0,size,65536):actual.update(restored.read(offset,min(65536,size-offset)))
    if actual.digest()!=digest.digest():raise ValueError('restored payload mismatch')
    strategy='rebuild_then_full'if repair and before&invalid else 'fallback_full'if before&invalid else 'validated_full'
    return {'strategy':strategy,'source_flags_before':before,'source_flags_after':after,'restored_sha256':actual.hexdigest(),'bytes':size}

